hints.text:
Un editor de HTML quiere comprobar que cada etiqueta de apertura se cierra con su pareja, solo con los tipos A, B y C.

function etiquetasOk(secuencia) {
  const parejas = { a: "A", b: "B", c: "C" };
  const abiertas = [];
  for (const e of secuencia) {
    if (e === "A" || e === "B" || e === "C") abiertas.push(e);
    else if (parejas[e] !== undefined) {
      if (abiertas.pop() !== parejas[e]) return false;
    }
  }
  return abiertas.length === 0;
}
